import EarthViewer from "./components/EarthViewer";

export default function App() {
  return (
    <div
      style={{
        width: "100vw",
        height: "100vh",
        background: "#000011",
        position: "relative",
      }}
    >
      <EarthViewer />
      <div
        style={{
          position: "absolute",
          top: 20,
          left: 20,
          color: "white",
          background: "rgba(0,0,0,0.5)",
          padding: "8px",
          borderRadius: "8px",
          zIndex: 10,
        }}
      >
        Overlay Test
      </div>
    </div>
  );
}
